 ob=bpy.data.objects[pane];shrunk=[ob.matrix_world@v.co for v in ob.data.vertices[:4]];center=sum(shrunk,Vector())/4;short=min((a-b).length for a,b in zip(shrunk,shrunk[1:]+shrunk[:1]));factor=1-.055/(short+.055);assert factor>.85;ps=[center+(p-center)/factor for p in shrunk];n=((ob.matrix_world@ob.data.vertices[0].co)-(ob.matrix_world@ob.data.vertices[4].co)).normalized();plane=(shrunk[1]-shrunk[0]).cross(shrunk[3]-shrunk[0]).normalized();n=plane if plane.dot(n)>0 else -plane;pane=dict(name=ob.name,source_polygon=[list(p) for p in ps],normal=list(n));a=ps[0];u=(ps[1]-a).normalized();v=n.cross(u).normalized();poly=[[(p-a).dot(u),(p-a).dot(v)] for p in ps];trim=inset(poly,.012);assert len(trim)>=3;new=[a+u*x+v*y for x,y in trim];N=len(new);me=bpy.data.meshes.new(ob.name+'_metric_inset');inv=ob.matrix_world.inverted();me.from_pydata([tuple(inv@p) for p in new]+[tuple(inv@(p-n*cfg['glass_thickness_m'])) for p in new],[],[tuple(range(N-1,-1,-1)),tuple(range(N,2*N))]+[(i,(i+1)%N,(i+1)%N+N,i+N) for i in range(N)]);me.update();bm=bmesh.new();bm.from_mesh(me);bmesh.ops.recalc_face_normals(bm,faces=list(bm.faces));bm.to_mesh(me);bm.free()
